try:
    'A'.encode('ansi.x3.4.1986')
except LookupError as error:
    assert error.args == ('unknown encoding: ansi.x3.4.1986',)
else:
    assert False
try:
    b'A'.decode('ansi.x3.4.1986')
except LookupError as error:
    assert error.args == ('unknown encoding: ansi.x3.4.1986',)
else:
    assert False
try:
    str(b'A', 'ansi.x3.4.1986')
except LookupError as error:
    assert error.args == ('unknown encoding: ansi.x3.4.1986',)
else:
    assert False

